public struct FfiConverterTypeBindingError: FfiConverterRustBuffer {
    typealias SwiftType = BindingError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> BindingError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .Configuration(
            detailMessage: try FfiConverterString.read(from: &buf)
            )
        case 2: return .Transport(
            detailMessage: try FfiConverterString.read(from: &buf)
            )
        case 3: return .Service(
            grpcCode: try FfiConverterInt32.read(from: &buf), 
            serviceCode: try FfiConverterOptionInt32.read(from: &buf), 
            detailMessage: try FfiConverterString.read(from: &buf)
            )
        case 4: return .Contract(
            detailMessage: try FfiConverterString.read(from: &buf)
            )
        case 5: return .Semantic(
            detailMessage: try FfiConverterString.read(from: &buf)
            )
        case 6: return .Cancelled

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: BindingError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case let .Configuration(detailMessage):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(detailMessage, into: &buf)
            
        
        case let .Transport(detailMessage):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(detailMessage, into: &buf)
            
        
        case let .Service(grpcCode,serviceCode,detailMessage):
            writeInt(&buf, Int32(3))
            FfiConverterInt32.write(grpcCode, into: &buf)
            FfiConverterOptionInt32.write(serviceCode, into: &buf)
            FfiConverterString.write(detailMessage, into: &buf)
            
        
        case let .Contract(detailMessage):
            writeInt(&buf, Int32(4))
            FfiConverterString.write(detailMessage, into: &buf)
            
        
        case let .Semantic(detailMessage):
            writeInt(&buf, Int32(5))
            FfiConverterString.write(detailMessage, into: &buf)
            
        
        case .Cancelled:
            writeInt(&buf, Int32(6))
        
        }
    }
}


